import { describe, it, expect } from "vitest";
import { runScenario } from "./claim-office.js";

describe("MHPCO Claim Office", () => {
  describe("quote — base premiums", () => {
    it.todo("empty item list → premium 5 G (only the processing fee)");
    it.todo("newcomer, plain sword → premium 115 G (100 base + 10 first insurance + 5 fee)");
    it.todo("newcomer, plain amulet → premium 71 G (60 base + 6 first insurance + 5 fee)");
    it.todo("newcomer, plain staff → premium 93 G (80 base + 8 first insurance + 5 fee)");
    it.todo("newcomer, plain potion → premium 49 G (40 base + 4 first insurance + 5 fee)");
  });

  describe("quote — components and blocks", () => {
    it.todo("2 runes → 50 G base premium (premium 60 G)");
    it.todo("3 runes → 60 G base premium, block applies (premium 71 G)");
    it.todo("4 runes → 100 G base premium, no block (premium 115 G)");
    it.todo("7 runes → 175 G base premium (premium 198 G, 197.5 rounded up)");
    it.todo("2 runes + 1 moonstone → 75 G base premium, no block for different types (premium 88 G)");
    it.todo("3 runes + 3 moonstones → 120 G base premium, two blocks (premium 137 G)");
  });

  describe("quote — premium modifiers", () => {
    it.todo("newcomer with a cursed sword (steel, enchantment 3) → premium 165 G");
    it.todo("sword with enchantment 4 → no high-enchantment surcharge (premium 115 G)");
    it.todo("sword with exactly enchantment 5 → high-enchantment surcharge applies (premium 145 G)");
    it.todo("cursed sword with exactly enchantment 5 → both surcharges apply (premium 195 G)");
    it.todo("customer with exactly 2 years → loyalty discount applies (plain sword premium 95 G)");
    it.todo("cursed sword + plain amulet → curse surcharge only on the sword's base (210 G before policy modifiers; premium 231 G)");
    it.todo("second quote in a scenario receives 15 % follow-up discount (plain sword: 115 G, then 100 G)");
    it.todo("long-standing customer's second contract, cursed sword enchantment 7 → premium 160 G");
    it.todo("premium yielding 197.5 G is rounded up to 198 G");
  });

  describe("claim — reimbursement", () => {
    it.todo("regular sword (steel, enchantment 3), damage 500 G → payout 400 G");
    it.todo("rune, damage 200 G → payout 100 G");
    it.todo("steel sword, enchantment 9, damage 1000 G → payout 400 G");
    it.todo("dragon-material sword, enchantment 5, damage 800 G → payout 700 G");
    it.todo("dragon-material sword, enchantment 9, damage 1000 G → payout 400 G");
    it.todo("dragon-material sword, exactly enchantment 8, damage 1000 G → payout 400 G");
    it.todo("payout yielding 350.5 G is rounded down to 350 G (enchantment 9, damage 901 G)");
  });

  describe("claim — deductible and cap", () => {
    it.todo("dragon attack damages sword (500 G) and amulet (300 G) → payout 600 G, deductible per item");
    it.todo("claim result reports remainingCap: sword + amulet policy → cap 3200 G");
    it.todo("cursed sword policy → cap 2000 G based on unmodified insurance value");
    it.todo("sword + 3 runes policy → insurance sum 1750 G, cap 3500 G");
    it.todo("two swords policy → cap 4000 G; damage to both swords handled with separate deductibles");
    it.todo("two successive 1500 G claims on a sword → payouts 1400 G (cap 600 G) then 600 G (cap 0 G)");
  });

  describe("errors", () => {
    it.todo("quote with an unknown item type (broomstick) is rejected");
    it.todo("claim damaging an item not in the policy is rejected");
    it.todo("claim damaging an unknown item type is rejected");
    it.todo("claim with more damages of a type than the policy covers is rejected");
    it.todo("claim with a negative damage amount is rejected");
  });

  describe("CLI", () => {
    it.todo("reads a scenario from stdin and writes results JSON to stdout");
    it.todo("exits non-zero and writes an error to stderr with no results on invalid input");
  });
});

