cat > src/claim-office.ts <<'EOF'
export interface Item {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

export interface Damage {
  itemType: string;
  amount: number;
}

export type Step =
  | { op: "quote"; items: Item[] }
  | { op: "claim"; policy: number; incident: { cause: string; damages: Damage[] } };

export interface Scenario {
  customer: { yearsWithMHPCO: number };
  steps: Step[];
}

export type Result = { premium: number } | { payout: number; remainingCap: number };

export const runScenario = (_scenario: Scenario): { results: Result[] } => {
  return undefined as unknown as { results: Result[] };
};
EOF
pnpm test 2>&1 | grep -E "AssertionError|Expected|Received|Tests" | head

