type QuoteStep = Extract<Step, { op: "quote" }>;

const PROCESSING_FEE = 5;
const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
  moonstone: 25,
};
const COMPONENT_TYPES = ["rune", "moonstone"];
const COMPONENT_BLOCK_SIZE = 3;
const COMPONENT_BLOCK_BASE_PREMIUM = 60;
const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
const CURSE_SURCHARGE_PERCENT = 50;
const HIGH_ENCHANTMENT_THRESHOLD = 5;
const HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;

const percentOf = (percent: number, amount: number): number => (amount * percent) / 100;

const roundPremiumInMHPCOsFavour = (premium: number): number => Math.ceil(premium);

const withFirstInsuranceSurcharge = (basePremium: number): number =>
  basePremium + percentOf(FIRST_INSURANCE_SURCHARGE_PERCENT, basePremium);

const basePremiumOf = (item: Item): number => BASE_PREMIUMS[item.type];

const countOfType = (items: Item[], type: string): number =>
  items.filter((item) => item.type === type).length;

const totalBasePremium = (items: Item[]): number => {
  const blockedComponentTypes = COMPONENT_TYPES.filter((type) => countOfType(items, type) === COMPONENT_BLOCK_SIZE);
  const unblocked = items.filter((item) => !blockedComponentTypes.includes(item.type));
  return (
    blockedComponentTypes.length * COMPONENT_BLOCK_BASE_PREMIUM +
    unblocked.reduce((sum, item) => sum + basePremiumOf(item), 0)
  );
};

const isHighlyEnchanted = (item: Item): boolean => (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;

const itemSurchargePercent = (item: Item): number =>
  (item.cursed ? CURSE_SURCHARGE_PERCENT : 0) + (isHighlyEnchanted(item) ? HIGH_ENCHANTMENT_SURCHARGE_PERCENT : 0);

const itemSurcharges = (items: Item[]): number =>
  items.reduce((sum, item) => sum + percentOf(itemSurchargePercent(item), basePremiumOf(item)), 0);

const quotePremium = (items: Item[]): number =>
  roundPremiumInMHPCOsFavour(
    withFirstInsuranceSurcharge(totalBasePremium(items)) + itemSurcharges(items) + PROCESSING_FEE,
  );

export const runScenario = (scenario: Scenario): { results: Result[] } => {
  const quoteStep = scenario.steps[0] as QuoteStep;
  const premium = quotePremium(quoteStep.items);
  return { results: [{ premium }] };
};

