  basePremium + percentOf(policyModifierPercent(yearsWithMHPCO), basePremium);

const basePremiumOf = (item: Item): number => BASE_PREMIUMS[item.type];

const sumOver = (items: Item[], amountOf: (item: Item) => number): number =>
  items.reduce((sum, item) => sum + amountOf(item), 0);

