const payoutCap = (policyItems: Item[]): number =>
  CAP_MULTIPLIER * sumOver(policyItems, insuranceValueOf);

const settleClaim = (damages: Damage[], policyItems: Item[]): Result => {
  const payout = claimPayout(damages, policyItems);
  return { payout, remainingCap: payoutCap(policyItems) - payout };
};

const issueQuote = (items: Item[], yearsWithMHPCO: number, isFollowUp: boolean): Result => ({
  premium: quotePremium(items, yearsWithMHPCO, isFollowUp),
});

const insuredItemsOfPolicy = (steps: Step[], policy: number): Item[] =>
  (steps[policy] as Extract<Step, { op: "quote" }>).items;

export const runScenario = ({ customer, steps }: Scenario): { results: Result[] } => {
  const results = steps.map((step, index): Result => {
    if (step.op === "claim") {
      return settleClaim(step.incident.damages, insuredItemsOfPolicy(steps, step.policy));
    }
    const isFollowUp = index > 0;
    return issueQuote(step.items, customer.yearsWithMHPCO, isFollowUp);
  });
  return { results };
};

